package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var A int64
	fmt.Fscan(in, &A)

	// Factorize A
	n := A
	var p2 int64
	for n%2 == 0 {
		p2++
		n /= 2
	}
	factors := make([][2]int64, 0)
	if p2 > 0 {
		factors = append(factors, [2]int64{2, p2})
	}
	var p int64 = 3
	for p*p <= n {
		if n%p == 0 {
			var cnt int64
			for n%p == 0 {
				cnt++
				n /= p
			}
			factors = append(factors, [2]int64{p, cnt})
		}
		p += 2
	}
	if n > 1 {
		factors = append(factors, [2]int64{n, 1})
	}

	// Generate all divisors of A
	divs := []int64{1}
	for _, f := range factors {
		p, e := f[0], f[1]
		curSize := len(divs)
		mult := int64(1)
		for i := int64(1); i <= e; i++ {
			mult *= p
			for j := 0; j < curSize; j++ {
				divs = append(divs, divs[j]*mult)
			}
		}
	}

	// Check each divisor d: if d-1 divides A and A/(d-1) is prime
	var count int64
	for _, d := range divs {
		if d <= 1 {
			continue
		}
		k := d - 1
		if A%k != 0 {
			continue
		}
		p := A / k
		if isPrime(p) {
			count++
		}
	}

	fmt.Println(count)
}

func isPrime(n int64) bool {
	if n < 2 {
		return false
	}
	if n == 2 || n == 3 {
		return true
	}
	if n%2 == 0 {
		return false
	}
	var i int64 = 3
	for i*i <= n {
		if n%i == 0 {
			return false
		}
		i += 2
	}
	return true
}

