func main() {
	in := bufio.NewReader(os.Stdin)
	var A int64
	fmt.Fscan(in, &A)

	var ans int64 = 0
	var i int64
	for i = 1; i*i <= A; i++ {
		if A%i == 0 {
			d1 := i
			d2 := A / i

			// Check x = d1 - 1
			x1 := d1 - 1
			if x1 > 0 && sumDivisors(x1) == A {
				ans++
			}

			// Check x = d2 - 1, avoid double check when d1 == d2
			if d1 != d2 {
				x2 := d2 - 1
				if x2 > 0 && sumDivisors(x2) == A {
					ans++
				}
			}
		}
	}

	fmt.Println(ans)
}

func sumDivisors(n int64) int64 {
	var sum int64 = 0
	var i int64
	for i = 1; i*i <= n; i++ {
		if n%i == 0 {
			sum += i
			if i*i != n {
				sum += n / i
			}
		}
	}
	return sum
}

