	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var A int64
	fmt.Fscan(in, &A)

	// Precompute primes up to 1e6
	const MAX = 1000000
	isPrime := make([]bool, MAX+1)
	for i := 2; i <= MAX; i++ {
		isPrime[i] = true
	}
	for i := 2; i*i <= MAX; i++ {
		if isPrime[i] {
			for j := i * i; j <= MAX; j += i {
				isPrime[j] = false
			}
		}
	}

	var count int64

	// Case 1: x = p (prime), J(x) = 1 + p = A => p = A-1
	if A > 2 && A-1 <= MAX && isPrime[A-1] {
		count++
	}

	// Case 2: x = p^2, J(x) = 1 + p + p^2 = A
	// p must be prime and p^2 <= 1e12 => p <= 1e6
	for p := int64(2); p <= MAX; p++ {
		if !isPrime[p] {
			continue
		}
		p2 := p * p
		if p2 > A {
			break
		}
		if 1+p+p2 == A {
			count++
		}
	}

	// Case 3: x = p*q, p<q primes, J(x) = (1+p)(1+q) = A
	// For each prime p, check if A%(1+p)==0 and q = A/(1+p)-1 is prime > p
	for p := int64(2); p <= MAX; p++ {
		if !isPrime[p] {
			continue
		}
		t := 1 + p
		if t > A {
			break
		}
		if A%t != 0 {
			continue
		}
		q := A/t - 1
		if q <= p || q > MAX {
			continue
		}
		if isPrime[q] {
			count++
		}
	}

	fmt.Println(count)
}

