func main() {
	in := bufio.NewReader(os.Stdin)
	var A int64
	fmt.Fscan(in, &A)

	// Precompute primes up to 1e6
	const MAX = 1000000
	isPrime := make([]bool, MAX+1)
	for i := 2; i <= MAX; i++ {
		isPrime[i] = true
	}
	for i := 2; i*i <= MAX; i++ {
		if isPrime[i] {
			for j := i * i; j <= MAX; j += i {
				isPrime[j] = false
			}
		}
	}

	// Factorization of A
	type Factor struct {
		p int64
		e int
	}
	var factors []Factor
	tmp := A
	for i := int64(2); i*i <= tmp; i++ {
		if tmp%i == 0 {
			cnt := 0
			for tmp%i == 0 {
				tmp /= i
				cnt++
			}
			factors = append(factors, Factor{p: i, e: cnt})
		}
	}
	if tmp > 1 {
		factors = append(factors, Factor{p: tmp, e: 1})
	}

	// Generate all divisors of A
	var divisors []int64
	var gen func(pos int, cur int64)
	gen = func(pos int, cur int64) {
		if pos == len(factors) {
			divisors = append(divisors, cur)
			return
		}
		p := factors[pos].p
		e := factors[pos].e
		val := int64(1)
		for i := 0; i <= e; i++ {
			gen(pos+1, cur*val)
			val *= p
		}
	}
	gen(0, 1)

	// Check each divisor d if it can be a prime p with sum of divisors A
	var count int64
	for _, d := range divisors {
		if d <= 1 || d > MAX {
			continue
		}
		if !isPrime[d] {
			continue
		}
		p := d
		// A must be divisible by (p+1)
		if A%(p+1) != 0 {
			continue
		}
		// Compute k = A/(p+1)
		k := A / (p + 1)
		// Check if k is power of p: k = p^n, n>=1
		if k < p {
			continue
		}
		for k%p == 0 {
			k /= p
		}
		if k == 1 {
			count++
		}
	}

	// Special case: x = 1, J(1) = 1
	if A == 1 {
		count++
	}

	fmt.Println(count)
}

