func main() {
	in := bufio.NewReader(os.Stdin)
	var A int64
	fmt.Fscan(in, &A)

	// Factorize A
	n := A
	var primes []int64
	var exps []int64

	for p := int64(2); p*p <= n; p++ {
		if n%p == 0 {
			cnt := int64(0)
			for n%p == 0 {
				n /= p
				cnt++
			}
			primes = append(primes, p)
			exps = append(exps, cnt)
		}
	}
	if n > 1 {
		primes = append(primes, n)
		exps = append(exps, 1)
	}

	// Generate all divisors of A
	var divisors []int64
	var gen func(idx int, cur int64)
	gen = func(idx int, cur int64) {
		if idx == len(primes) {
			divisors = append(divisors, cur)
			return
		}
		val := int64(1)
		for i := int64(0); i <= exps[idx]; i++ {
			gen(idx+1, cur*val)
			val *= primes[idx]
		}
	}
	gen(0, 1)

	// Check each divisor d if there exists integer x with sigma(x)=A and gcd(x,A)=d
	var count int64
	for _, d := range divisors {
		// Compute B = A/d
		if A%d != 0 {
			continue
		}
		B := A / d
		// Factorize B
		b := B
		ok := true
		for p := int64(2); p*p <= b && ok; p++ {
			if b%p == 0 {
				cnt := int64(0)
				for b%p == 0 {
					b /= p
					cnt++
				}
				// Check if p divides A
				if A%p != 0 {
					ok = false
					break
				}
				// Check if p divides d
				if d%p != 0 {
					ok = false
					break
				}
			}
		}
		if !ok {
			continue
		}
		if b > 1 {
			// remaining prime factor
			p := b
			if A%p != 0 || d%p != 0 {
				continue
			}
		}
		count++
	}

	fmt.Println(count)
}

