func main() {
	in := bufio.NewReader(os.Stdin)
	var A int64
	fmt.Fscan(in, &A)

	var count int64 = 0
	var d int64 = 1
	for d*d <= A {
		if A%d == 0 {
			// candidate x = A/d - 1
			x := A/d - 1
			if x > 0 {
				if sumDivisors(x) == A {
					count++
				}
			}
			if d*d != A {
				// candidate x = d - 1
				x2 := d - 1
				if x2 > 0 {
					if sumDivisors(x2) == A {
						count++
					}
				}
			}
		}
		d++
	}

	fmt.Println(count)
}

func sumDivisors(n int64) int64 {
	var sum int64 = 0
	var i int64 = 1
	for i*i <= n {
		if n%i == 0 {
			sum += i
			if i*i != n {
				sum += n / i
			}
		}
		i++
	}
	return sum
}

