import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var A int64
	fmt.Fscan(in, &A)

	// Factorize A
	type Factor struct {
		p int64
		e int
	}
	var factors []Factor

	n := A
	for d := int64(2); d*d <= n; d++ {
		if n%d == 0 {
			e := 0
			for n%d == 0 {
				n /= d
				e++
			}
			factors = append(factors, Factor{p: d, e: e})
		}
	}
	if n > 1 {
		factors = append(factors, Factor{p: n, e: 1})
	}

	// Check for impossible cases
	for _, f := range factors {
		if f.p == 2 {
			// 2^e factor
			if f.e == 1 {
				// A has factor 2^1 -> impossible
				fmt.Println(0)
				return
			}
		} else {
			// odd prime factor must have exponent 1
			if f.e > 1 {
				fmt.Println(0)
				return
			}
		}
	}

	// Count odd prime factors
	oddCount := 0
	for _, f := range factors {
		if f.p != 2 {
			oddCount++
		}
	}

	// If A is odd, no solution
	if A%2 == 1 {
		fmt.Println(0)
		return
	}

	// If A is power of 2
	if oddCount == 0 {
		// A = 2^k, k>=2
		fmt.Println(1)
		return
	}

	// General case: A = 2^k * product of distinct odd primes, k>=2
	// Number of solutions is 2^(oddCount - 1)
	ans := int64(1)
	for i := 0; i < oddCount-1; i++ {
		ans *= 2
	}
	fmt.Println(ans)
}

