	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var A int64
	fmt.Fscan(in, &A)

	// Precompute primes up to 1e6
	const MAX = 1000000
	isPrime := make([]bool, MAX+1)
	for i := 2; i <= MAX; i++ {
		isPrime[i] = true
	}
	for i := 2; i*i <= MAX; i++ {
		if isPrime[i] {
			for j := i * i; j <= MAX; j += i {
				isPrime[j] = false
			}
		}
	}

	var count int64

	// Case 1: x is prime => J(x) = 1 + x = A => x = A - 1
	if A > 1 {
		x := A - 1
		if x <= MAX && isPrime[x] {
			count++
		}
	}

	// Case 2: x = p^2, p prime => J(x) = 1 + p + p^2 = A
	// Solve p^2 + p + 1 = A
	// p is integer, check p prime
	for p := int64(2); p*p <= A; p++ {
		if p > MAX {
			break
		}
		if !isPrime[p] {
			continue
		}
		if p*p+p+1 == A {
			count++
		}
	}

	// Case 3: x = p*q, p <= q primes => J(x) = (1+p)(1+q) = A
	// Iterate p over primes, check if A % (1+p) == 0 and q = A/(1+p) - 1 is prime
	for p := int64(2); p <= MAX && (1+p)*(1+p) <= A; p++ {
		if !isPrime[p] {
			continue
		}
		s := 1 + p
		if A%s != 0 {
			continue
		}
		t := A / s
		q := t - 1
		if q < p || q > MAX {
			continue
		}
		if isPrime[q] {
			count++
		}
	}

	fmt.Println(count)
}
